-- Rivals Coach — correctif de l'import par capture, guides Nightcrawler et Loki refaits
--   · profiles : droit de lecture sur ingame_name et accept_shared_imports. Il manquait dans la 0017 :
--     la lecture de profiles est accordée colonne par colonne depuis la 0006, et sans lui l'écran
--     d'import se croyait désactivé.
--   · guide Nightcrawler réécrit à partir de deux vidéos de l'accès anticipé (kit complet, combos, plan de jeu)
--   · guide Loki réécrit à partir d'une masterclass vidéo
--   · quiz : questions Nightcrawler corrigées, deux questions ajoutées
-- À exécuter après 0017_capture_import.sql. Ré-exécutable.

-- 1. Import par capture
grant select (ingame_name, accept_shared_imports) on public.profiles to authenticated;

-- 2. Guides
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Loki est un soigneur de zone. Tout son soin vient de l'explosion de ses projectiles, et ses deux clones tirent là où il tire : un seul clic peut soigner trois fois toute une ligne de front. Ses runes transforment en soin les dégâts subis par ses alliés, et son ult copie n'importe quel héros, ult comprise. Il demande une attention constante, pas une mécanique difficile.", "patch_note": "Guide rédigé à partir d'une masterclass vidéo antérieure à la saison 11 et des notes de patch. Les principes en sont repris ; les chiffres, qui ont pu changer, sont laissés de côté. Loki a été retiré de plusieurs modes pendant la saison 10 : vérifie sa disponibilité en jeu.", "tldr": ["**Vise le sol** aux pieds de tes tanks : seul le souffle de l'explosion soigne.", "**Deux clones en jeu, tout le temps** : chacun triple presque tes soins.", "Garde les **runes** pour l'ult adverse, et **copie une ult de support**."], "difficulty": 3, "tags": ["Soin de zone", "Clones", "Anti-ult", "Copie d'ult"], "strengths": ["Soin de zone triplé par les clones", "Runes qui annulent une ult de dégâts", "Copie de n'importe quelle ult", "Très dur à attraper (échange, invisibilité)"], "weaknesses": ["Peu efficace avec une équipe aérienne ou dispersée", "Deux divers à la suite épuisent ses cooldowns", "Clones et runes effacés par certaines ults", "Clones utilisés par l'ennemi (ricochets, charges)"], "playbook": [{"when": "Ton équipe est groupée et entamée", "then": "Tire **au sol entre tes alliés**, tes deux clones en vue de la zone : le souffle les soigne tous, et blesse les ennemis au contact."}, {"when": "Une ult de dégâts tombe sur ton équipe (Iron Man, Psylocke, Groot)", "then": "**Envoie un clone au milieu, puis runes** : elles apparaissent sous toi et sous chaque clone. Les dégâts subis dedans deviennent du soin."}, {"when": "Un diver te saute dessus", "then": "**Échange de place** d'abord : il doit se retourner pour te retrouver. **Invisibilité** ensuite, quand il ne te tire plus dessus."}, {"when": "Tu es poursuivi dans un couloir", "then": "L'échange **traverse les murs** : passe sur le clone resté dans l'autre pièce. Sans cible, la touche t'envoie sur le clone le plus proche."}, {"when": "Un clone vient de tomber et tes deux charges sont en cooldown", "then": "**Invisibilité, puis tire aussitôt** : elle laisse un clone à ta place, sans dépenser de charge."}, {"when": "Ton autre support n'a pas d'ult de zone, ou vient de lancer la sienne", "then": "**Copie un support**, allié ou ennemi, et pose son ult sur le point. Invisible, tu peux aller chercher celui d'en face."}, {"when": "Un adversaire pose des runes ou des clones (Loki en face)", "then": "**Tire sur les pierres runiques**, jamais sur les joueurs dans le champ : tes dégâts les soigneraient."}], "sections": [{"title": "Philosophie de jeu", "lead": "Loki n'est pas un soigneur de fond de carte. Il joue dans le dos de ses Vanguards, vise leurs pieds et garde toujours une capacité prête pour lui. Son plafond est très haut, à condition de rester actif en permanence.", "ability": "", "key": "", "kind": "default", "items": ["**Reste près de ta ligne de front** : isolé à l'arrière, tu dépenses tes cooldowns pour survivre. Près des tanks, tes runes profitent à tout le monde.", "Ton premier objectif : que tes Vanguards **n'aient jamais à reculer**. Les dégâts aux ennemis viennent tout seuls, par le souffle de tes tirs.", "Surveille tes clones en permanence et **remplace-les** dès qu'il en manque un.", "Il souffre avec une équipe de volants ou une ligne de front fragile : son soin a besoin d'alliés regroupés au sol.", "Au début, joue un peu plus loin, le temps d'apprendre tes cooldowns."], "diagram": "heal"}, {"title": "Projectiles mystiques", "lead": "Le projectile lui-même ne fait rien : tout le soin et tous les dégâts sont dans l'explosion à l'impact. Elle ne te soigne pas.", "ability": "Mystical Missile", "key": "Clic G", "kind": "default", "items": ["**Toucher un allié ou le sol à côté de lui revient au même** : vise le sol, au milieu de ta ligne de front, pour soigner plusieurs alliés d'un coup.", "Tes clones tirent **là où tu tires**, s'ils voient l'endroit : avec deux clones, chaque clic compte triple.", "Le soin est le même dans toute l'explosion ; les dégâts, eux, diminuent loin du centre.", "**Prends un peu de hauteur**, même un simple saut : il est plus facile de viser le sol de haut en bas.", "Soigner un tank qui se bat au corps à corps blesse aussi son adversaire, et charge ton ult très vite."], "diagram": ""}, {"title": "Clones", "lead": "Tu poses une illusion à l'endroit visé, à bonne distance. Elle ne bouge pas, mais elle reproduit tes tirs et tes runes. Deux charges.", "ability": "Doppelganger", "key": "Clic D", "kind": "default", "items": ["**Deux clones en jeu en permanence** : c'est toute la différence entre un Loki moyen et un bon.", "Place-les là où ils **voient ton équipe** : un clone sans ligne de vue ne soigne personne.", "Garde-en un **à l'abri ou dans une autre pièce** : c'est ta sortie avec l'échange de place.", "Ils restent en jeu après ta mort : au retour, saute de clone en clone pour revenir plus vite.", "Sur un convoi en attaque, pose-les **sur le convoi** : ils avancent avec lui.", "Deux clones aux pieds d'un ennemi isolé, et tes tirs deviennent une vraie menace.", "Avec le team-up d'Hela, un clone détruit met désormais tes capacités de clone une seconde en cooldown (saison 11)."], "diagram": ""}, {"title": "Runes", "lead": "Un champ de soin apparaît sous toi et sous chaque clone. Tant qu'un allié s'y trouve, il est soigné en continu et les dégâts qu'il subit deviennent du soin. Le champ tient à des pierres runiques, qui peuvent être détruites.", "ability": "Regeneration Domain", "key": "Maj", "kind": "default", "items": ["C'est une **petite ult**, au cooldown long : elle annule la plupart des ults de dégâts. Ne la gaspille pas.", "**Pour sauver un allié précis** : pose un clone à côté de lui, puis lance les runes. Elles apparaissent aussi sous le clone.", "Elle sert aussi de bouton d'urgence, et de réponse à un diver : dans le champ, toi et ton autre support pouvez lui tirer dessus sans mourir.", "On ne passe pas en force : seule la **destruction des pierres** met fin au champ. Black Widow les casse d'un tir.", "Certaines ults effacent le champ lui-même : **Magik, Storm, Phoenix**.", "Elles ne protègent pas d'un **déplacement forcé** : un allié sorti du champ redevient vulnérable.", "Depuis la saison 11, le team-up de Mantis ne donne plus de bonus de dégâts dans le champ."], "diagram": "", "scene": {"title": "Clones et runes", "caption": "Chaque clone pose son propre champ de runes. Deux clones bien placés couvrent toute ton équipe.", "steps": ["Deux clones posés avant le fight, sur des angles différents.", "Une ult de dégâts arrive : runes. Chaque clone pose les siennes.", "Les dégâts subis dans les champs deviennent du soin."], "els": [{"t": "pawn", "at": [52, 96], "team": "me"}, {"t": "mark", "at": [120, 60], "kind": "clone", "team": "me", "label": "Clone"}, {"t": "mark", "at": [124, 134], "kind": "clone", "team": "me", "label": "Clone"}, {"t": "note", "at": [88, 60], "text": "1", "team": "me"}, {"t": "zone", "at": [52, 96], "r": 24, "team": "me"}, {"t": "zone", "at": [124, 62], "r": 26, "team": "me", "n": 2}, {"t": "zone", "at": [126, 132], "r": 26, "team": "me"}, {"t": "pawn", "at": [146, 72], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [150, 122], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [100, 100], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [70, 140], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [258, 50], "team": "enemy", "hero": "iron-man", "above": true}, {"t": "path", "kind": "beam", "team": "enemy", "pts": [[258, 50], [150, 100]]}, {"t": "note", "at": [228, 104], "text": "dégâts convertis en soin", "team": "me"}, {"t": "note", "at": [228, 120], "text": "3", "team": "me"}, {"t": "pawn", "at": [254, 148], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [300, 90], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [294, 140], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [214, 160], "team": "enemy", "role": "dps"}]}}, {"title": "Invisibilité et échange", "lead": "Deception te rend invisible, te soigne et laisse un clone à ta place. Devious Exchange échange ta position avec celle d'un clone.", "ability": "Deception · Devious Exchange", "key": "E · F", "kind": "default", "items": ["L'échange **traverse les murs** et ne demande aucune ligne de vue.", "Sans viser de clone, la touche t'envoie **sur le plus proche**. En urgence seulement : tu ne choisis pas où tu arrives.", "**Échange d'abord, invisibilité ensuite** : attaqué pendant l'invisibilité, tu redeviens visible aussitôt.", "Tu peux **poser tes clones en restant invisible**. Un contact avec un ennemi te révèle, et il entend tes pas.", "L'invisibilité laisse un clone : c'est un **troisième moyen d'en poser un**, sans dépenser de charge.", "Avalé par Jeff ? Spamme l'échange : tu rejoins un clone dès qu'il te recrache.", "Le coup dans le dos inflige un bonus, mais tes tirs avec un clone font mieux : ne le cherche pas.", "Deception revient en 18 secondes depuis la saison 11. Daredevil et les marques d'Elsa Bloodstone te voient invisible."], "diagram": ""}, {"title": "Ultime", "lead": "Tu te transformes en un héros, allié ou ennemi. Tu disposes de tout son kit, cooldowns prêts, ult comprise.", "ability": "God of Mischief", "key": "Q", "kind": "default", "items": ["**Copie d'abord un support** : Luna Snow, Cloak & Dagger, Invisible Woman. Une ult de zone posée au bon moment gagne le fight.", "S'il n'y a pas d'urgence, **utilise d'abord les capacités** du héros copié, puis son ult en fin de transformation : elle la prolonge.", "Avec un héros à invocations (Rocket), lance l'ult **tout de suite** : tout disparaît quand tu redeviens Loki.", "Tu prends la vie entière du héros copié, mais tu **retrouves ta vie d'avant** à la fin : reviens à couvert avant.", "Les **team-ups ne sont pas copiés**.", "Les meilleurs Loki connaissent les autres supports : entraîne-toi sur ceux que tu copies le plus.", "Un Duelist ne vaut la copie que si tu sais le jouer."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "default", "items": ["Viser les alliés **au lieu du sol**.", "Jouer avec **un seul clone**, ou aucun.", "Rester **seul à l'arrière**, loin de ses tanks.", "Poser les runes **avant** l'ult adverse.", "Lancer l'invisibilité **sous le feu** d'un ennemi.", "Copier un héros **qu'on ne sait pas jouer**."], "diagram": ""}], "combos": [], "counters": [{"hero": "phoenix", "note": "Son ult efface d'un coup tes clones et tes runes."}, {"hero": "black-widow", "note": "Un tir suffit à casser tes pierres runiques, et son coup de pied interrompt ta copie."}, {"hero": "magik", "note": "Son ult détruit le champ de runes avant de te tuer."}, {"hero": "storm", "note": "Son ult balaie les runes, et elle vole hors de portée de ton souffle."}, {"hero": "black-panther", "note": "Seul, tu lui échappes. Suivi d'un second diver, tu n'as plus de cooldowns."}, {"hero": "moon-knight", "note": "Ses tirs ricochent sur tes clones et chargent son ult."}], "synergies": [{"hero": "luna-snow", "note": "Tu copies son ult : deux zones de soin à la suite."}, {"hero": "cloak-and-dagger", "note": "Une ult de zone facile à copier et à poser sur le point."}, {"hero": "the-thing", "note": "Un tank de mêlée immobile au milieu du fight : la cible idéale pour ton souffle."}, {"hero": "mantis", "note": "Votre team-up renforce ton champ de runes."}, {"hero": "doctor-strange", "note": "Derrière son bouclier, tes clones restent en vie tout le fight."}], "sources": [{"title": "Loki Masterclass - Advanced Guide in Marvel Rivals", "author": "YouTube", "url": "https://www.youtube.com/watch?v=fEAhTeGtObg"}, {"title": "Notes d'équilibrage de la saison 11", "author": "GameRiv", "url": "https://gameriv.com/marvel-rivals-season-11-balance-patch-notes/"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Odin's Unacknowledged", "partners": ["angela"], "key": "", "text": "Une illusion d'estoc projette les ennemis (dégâts max encaissés : 150 depuis la saison 10). **Amélioré :** Deux charges."}, {"name": "Vibrant Vitality", "partners": ["mantis"], "key": "", "text": "Domaine de régénération renforcé, sans bonus de dégâts pour les alliés depuis la saison 11. **Amélioré :** Onde de choc qui projette en blessant."}, {"name": "Villain's Illusion", "partners": ["hela"], "key": "", "text": "Prend la forme d'un héros tombé. Depuis la saison 11, une illusion détruite met Doppelganger et Devious Exchange 1 s en cooldown. **Amélioré :** Dure plus longtemps et empêche la mort."}], "changes": [{"season": "Saison 11", "text": "Deception : cooldown 15 → 18 s."}, {"season": "Saison 11", "text": "Team-up avec Hela : quand une illusion est détruite, Doppelganger et Devious Exchange passent 1 s en cooldown."}, {"season": "Saison 11", "text": "Team-up avec Mantis : plus de bonus de dégâts pour les alliés dans le Regeneration Domain."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'loki' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Nightcrawler est le Strategist de la saison 11, et le plus difficile à ce jour. Il ne se joue pas comme un soigneur : ses téléportations et ses dashes soignent, déplacent ses alliés et attirent les ennemis. Son travail est de créer des occasions pour son équipe, surtout avec une compo de dive, puis de revenir en sécurité.", "patch_note": "Guide rédigé à partir de deux vidéos tournées sur l'accès anticipé de la saison 11. Nightcrawler vient de sortir : son équilibrage peut encore changer, et aucun chiffre de dégâts ou de soin n'est donné ici.", "tldr": ["**Ne joue pas soigneur de fond** : ton kit sert à créer des occasions.", "**Smoke Shift** : deux dashes qui attirent les ennemis, le troisième te ramène au départ.", "**Tandem Teleport** amène un allié **là où tu te trouves** : pour le sauver, ou pour l'envoyer sur une cible."], "difficulty": 3, "tags": ["Téléportation", "Dive", "Sauvetage", "Création d'occasions"], "strengths": ["Très dur à attraper (deux téléportations, dashes invulnérables)", "Sauve ou projette un allié avec Tandem Teleport", "Ult d'engage : toute l'équipe arrive boostée", "Solide en duel contre un diver"], "weaknesses": ["Soins faibles pour un Strategist", "Peu utile sans compo de dive ni coéquipier qui suit", "Tandem Teleport dépend de l'accord de l'allié", "Décevant en file solo"], "playbook": [{"when": "Ton diver s'engage sur leur backline", "then": "**Swift Intervention** sur lui : soin immédiat, bonus de soins reçus, vitesse pour vous deux. Garde ta **seconde charge** pour revenir."}, {"when": "Un allié va plonger et risque de ne pas ressortir", "then": "**Tandem Teleport** avant qu'il parte : il a cinq secondes pour accepter et revenir sur toi, même étourdi."}, {"when": "Tu veux lancer un engage toi-même", "then": "Grenades, puis **Smoke Shift** : le premier dash t'amène au contact, le second attire et frappe encore, le troisième te ramène à la fumée."}, {"when": "Tu veux envoyer un allié sur une cible", "then": "Lance l'invitation, **dash sur la cible** : ton allié accepte et arrive sur toi, soigné, au milieu d'eux."}, {"when": "Un diver te colle", "then": "**Trois épées** : elles peuvent toucher à la tête. Si le duel tourne mal, téléporte-toi sur un allié éloigné."}, {"when": "Ton équipe est prête à engager", "then": "**Ult** sur leur position : tous les alliés autour de toi arrivent avec soin, bonus de dégâts et vie bonus. **Relance** pour ramener les ennemis sur toi."}, {"when": "Leur équipe s'abrite dans une ult de soin (Invisible Woman, Luna Snow)", "then": "Pose ton ult à côté et **relance** : tu les sors de la zone. Annonce-le pour que ton équipe frappe à l'arrivée."}], "sections": [{"title": "Plan de jeu", "lead": "Tout son kit pousse à quitter la backline, à faire quelque chose d'utile, puis à y revenir. Un Nightcrawler qui reste en arrière à lancer des grenades soigne moins bien que n'importe quel autre support.", "ability": "", "key": "", "kind": "default", "items": ["Il brille avec une **compo de dive** : Venom, Spider-Man, Daredevil. Il les rejoint, les soigne sur place et frappe la cible avec eux.", "Version plus sûre : reste en retrait et **pose Tandem Teleport sur un diver**, qui peut alors s'engager à fond avec une sortie garantie.", "**Smoke Shift crée de l'espace** : tu entres, tu attires leur ligne de front, tu forces les cooldowns de leurs supports, tu reviens.", "**Ne colle pas ton équipe** : une téléportation de deux mètres ne sauve personne. Garde toujours en tête l'allié éloigné sur lequel tu peux fuir.", "Il grimpe aux murs sans cooldown, et s'y perche s'il reste immobile : de quoi soigner d'en haut ou préparer un engage.", "Joue-le **à deux** si tu peux : en file solo, peu d'alliés acceptent ou suivent ses téléportations."], "diagram": ""}, {"title": "Grenades", "lead": "Une rafale de trois grenades qui explosent à l'impact : dégâts pour les ennemis, soin pour les alliés.", "ability": "Forged Brimstone", "key": "Clic G", "kind": "default", "items": ["**Suis ta cible pendant toute la rafale** : les trois grenades doivent toucher.", "Un coup direct soigne et blesse davantage, mais **viser les pieds** reste le plus fiable.", "La distance ne réduit pas le soin : elle rend seulement le tir plus difficile.", "Lance toujours une rafale **avant un Smoke Shift**."], "diagram": ""}, {"title": "Trois épées", "lead": "Une série d'estocs avec ses deux sabres et l'épée tenue par sa queue. Elle consomme une jauge au lieu d'avoir un cooldown, et peut toucher à la tête.", "ability": "Three-Sword Style", "key": "Clic D", "kind": "default", "items": ["C'est ton arme **contre un diver** : elle te permet de gagner le duel au lieu de fuir.", "**Ne vide pas la jauge** : dans le rouge, elle se recharge beaucoup plus lentement.", "Au contact, **glisse quelques estocs entre deux rafales** de grenades : plus de dégâts, et des coups directs plus faciles.", "Jauge vide, remplace les estocs par un coup de mêlée."], "diagram": ""}, {"title": "Téléportation de soutien", "lead": "Tu te téléportes instantanément sur un allié. Il reçoit un soin immédiat et un bonus de soins reçus, et vous gagnez tous les deux un peu de vitesse. Deux charges.", "ability": "Swift Intervention", "key": "Maj", "kind": "default", "items": ["Tu es **invulnérable pendant la téléportation** : elle ne peut pas être interrompue.", "**Une charge pour aller, une pour revenir** : rejoins ton diver, puis reviens sur un allié à l'abri.", "Deux secondes séparent les deux utilisations : tu ne ressors pas instantanément.", "Elle ne cible que des alliés : c'est aussi ta **fuite**, à condition d'en avoir un à distance.", "Le bonus de soins reçus profite aussi aux soins de ton autre support."], "diagram": ""}, {"title": "Fumée", "lead": "Premier appui : un dash tournoyant qui blesse les ennemis, soigne un peu les alliés autour et laisse un nuage de fumée au départ. Deuxième appui : un saut vers l'avant qui frappe encore. Troisième appui : retour au nuage.", "ability": "Smoke Shift", "key": "E", "kind": "default", "items": ["Un ennemi que tu **traverses ou frôles est attiré vers toi** : sers-t'en pour déplacer une cible ou tirer leur ligne de front en arrière.", "Tu as **quelques secondes entre chaque appui** : frappe ou soigne avant d'enchaîner.", "Tu es **insensible aux contrôles** pendant les dashes.", "Vise le sol pour un simple burst de dégâts sur place.", "**Garde le troisième appui** : c'est ton retour. Dépense-le trop tôt et tu restes au milieu d'eux."], "diagram": ""}, {"title": "Téléportation à deux", "lead": "Tu envoies une invitation à un allié. S'il l'accepte dans les cinq secondes, il est téléporté là où tu te trouves, avec un soin immédiat et un soin continu.", "ability": "Tandem Teleport", "key": "F", "kind": "default", "items": ["**Sauvetage** : un allié trop avancé revient sur toi. Elle fonctionne même s'il est étourdi ou pris dans une ult de contrôle.", "**Engage** : lance l'invitation, dash sur une cible, et ton allié arrive sur toi, au contact. Idéal pour poser l'ult d'un Duelist au milieu d'eux.", "L'allié arrive à ta position **au moment où il accepte**, pas à celle du lancement : place-toi en conséquence.", "Pendant ces cinq secondes, il peut s'engager à fond : la sortie l'attend.", "Il voit un effet violet et un message à l'écran. **Annonce-la quand même** : en file solo, beaucoup ne l'acceptent pas."], "diagram": "", "scene": {"title": "Ramener un allié", "caption": "L'allié est ramené là où tu te trouves quand il accepte. Pour un sauvetage, reste à couvert.", "steps": ["Ton tank est isolé et entamé au milieu des ennemis.", "Tu lances l'invitation : il a cinq secondes pour accepter.", "Il est ramené sur toi, derrière le mur, et soigné."], "els": [{"t": "cover", "at": [108, 80], "size": [14, 48], "label": "Mur"}, {"t": "path", "kind": "move", "team": "me", "pts": [[80, 96], [150, 20], [210, 84]], "n": 2}, {"t": "pawn", "at": [226, 92], "team": "ally", "role": "tank", "ghost": true}, {"t": "note", "at": [226, 66], "text": "1", "team": "ally"}, {"t": "pawn", "at": [206, 96], "team": "me", "ghost": true}, {"t": "path", "kind": "pull", "team": "me", "pts": [[212, 106], [150, 186], [84, 116]], "n": 3}, {"t": "pawn", "at": [72, 108], "team": "me"}, {"t": "pawn", "at": [66, 74], "team": "ally", "role": "tank", "label": "Sauvé", "above": true}, {"t": "pawn", "at": [256, 62], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [258, 122], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [292, 92], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [296, 136], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [294, 34], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [36, 134], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [58, 162], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [30, 56], "team": "ally", "role": "dps"}]}}, {"title": "Ultime", "lead": "Tu lances ton épée vers une destination et tu t'y téléportes avec tous les alliés qui se trouvaient autour de toi. Ils reçoivent un soin, un bonus de dégâts et beaucoup de vie bonus. Un cercle de fumée se forme à l'arrivée : pendant six secondes, tu peux relancer l'ult pour frapper les ennemis qui s'y trouvent et les téléporter sur toi.", "ability": "Phasing Finale", "key": "Q", "kind": "default", "items": ["C'est une **ult d'engage**, pas une ult de soin : lance-la quand ton équipe est regroupée et prête à se battre.", "**Seuls les alliés téléportés** reçoivent les bonus. Ceux qui étaient déjà à l'arrivée n'ont rien.", "La relance ne prend que les ennemis **dans la fumée et en ligne de vue** : place-toi avant d'appuyer.", "**Sortir une équipe d'une ult de soin** adverse : pose l'ult à côté, relance, et ils se retrouvent hors de leur zone.", "Avec le team-up de Rogue amélioré : ramène-les avec la relance, puis écrase-les tous au même endroit.", "Dans les réglages propres au héros, active l'option qui laisse tes alliés **refuser la téléportation** : celui qui tient un flanc n'est pas arraché à sa position."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "default", "items": ["Le jouer comme un **soigneur de fond**.", "Dépenser ses **deux téléportations** pour entrer.", "Utiliser le troisième appui de Smoke Shift **trop tôt**.", "Rester collé à son équipe : **plus personne sur qui fuir**.", "Lancer l'ult **loin de ses alliés**.", "Vider la jauge des épées."], "diagram": ""}], "combos": [{"title": "Engage", "steps": [{"key": "Clic G", "label": "grenades"}, {"key": "E", "label": "dash"}, {"key": "Clic D", "label": "épées"}, {"key": "E", "label": "second dash"}, {"key": "E", "label": "retour"}], "note": "Le premier dash ferme la distance, le second finit la cible, le troisième te ramène à la **fumée**."}, {"title": "Avec le team-up de Rogue", "steps": [{"key": "Clic G", "label": "grenades"}, {"key": "E", "label": "dash"}, {"key": "C", "label": "team-up"}, {"key": "E", "label": "second dash"}], "note": "Sans ce team-up, remplace-le par un **coup de mêlée**."}, {"title": "Envoyer un allié", "steps": [{"key": "F", "label": "invitation"}, {"key": "E", "label": "dash sur la cible"}, {"key": "", "label": "l'allié accepte"}, {"key": "E", "label": "retour"}], "note": "Ton allié arrive **sur toi**, soigné, au milieu de leur backline."}], "counters": [{"hero": "hela", "note": "Elle te punit à l'arrivée de chaque téléportation, quand tu apparais à découvert."}, {"hero": "the-thing", "note": "Sa zone bloque les déplacements : tes sorties aussi, a priori. À vérifier en jeu."}, {"hero": "namor", "note": "Ses tourelles couvrent la backline où tu veux entrer."}, {"hero": "peni-parker", "note": "Ses mines et sa toile attendent ton dash."}], "synergies": [{"hero": "venom", "note": "Un tank de dive : tu le suis, tu le soignes sur place, et tu le ramènes s'il reste coincé."}, {"hero": "spider-man", "note": "Tu le rejoins sur son flanc, et Tandem Teleport lui offre une sortie."}, {"hero": "daredevil", "note": "Tu l'envoies sur une cible avec Tandem Teleport."}, {"hero": "rogue", "note": "Votre team-up ajoute une capacité qui attire les ennemis : dévastatrice après ton ult."}, {"hero": "magik", "note": "Votre team-up fait soigner chacun de tes déplacements, et te donne de la vie bonus."}, {"hero": "scarlet-witch", "note": "Tandem Teleport pose son ult au milieu de l'équipe adverse."}], "sources": [{"title": "ULTIMATE NIGHTCRAWLER GUIDE (Beginner/Advanced)", "author": "YouTube", "url": "https://www.youtube.com/watch?v=L84u9R5Uv1A"}, {"title": "NIGHTCRAWLER EARLY ACCESS! Every Ability & Combo Explained", "author": "YouTube", "url": "https://www.youtube.com/watch?v=-5-KLT1-om0"}, {"title": "Nightcrawler Is Here: Character Abilities Guide", "author": "esportnow.gg", "url": "https://esportnow.gg/games/news/nightcrawler-is-here-marvel-rivals-character-abilities-guide"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Demon Disciple", "partners": ["magik"], "key": "", "text": "Chaque capacité de déplacement (les deux téléportations, Smoke Shift) émet une onde qui soigne les alliés et blesse les ennemis autour de lui. **Amélioré :** Avec Magik dans l'équipe, chaque onde lui donne de la vie bonus, plafonnée."}, {"name": "Protective Siblings", "partners": ["rogue"], "key": "", "text": "Nouvelle capacité : Nightcrawler disparaît vers le ciel (dégâts, soin aux alliés), puis s'écrase au sol (dégâts, ralentissement). **Amélioré :** Avec Rogue dans l'équipe, l'impact attire tous les ennemis vers lui."}], "changes": [], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'nightcrawler' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);

-- 3. Quiz (la bonne réponse est rangée en premier, l'app mélange les options)
insert into public.quiz_questions (key, hero_id, map_id, guide_slug, topic, prompt, options, answer, explain, section) values
('nightcrawler-1', (select id from public.heroes where slug = 'nightcrawler'), null, null, 'Mise en situation', 'Ton tank est isolé au milieu des ennemis et tu lances Tandem Teleport. Où te placer ?', '["À couvert : il est ramené là où je me trouve quand il accepte", "Au milieu du fight, pour qu''il n''ait pas loin à aller", "Peu importe : il réapparaît à son point de départ", "Sur une hauteur à découvert, pour qu''il me voie"]'::jsonb, 0, 'L''allié a cinq secondes pour accepter l''invitation, même étourdi, et il arrive sur toi avec un soin. Pour un sauvetage, reste à couvert. La même capacité sert à l''inverse : dash sur une cible, et ton allié arrive au contact.', 'Téléportation à deux'),
('nightcrawler-4', (select id from public.heroes where slug = 'nightcrawler'), null, null, 'Kit', 'À quoi sert le troisième appui de Smoke Shift ?', '["À revenir au nuage de fumée laissé au départ", "À dasher une troisième fois vers l''avant", "À soigner toute ton équipe", "À devenir invisible"]'::jsonb, 0, 'Les deux premiers appuis sont des dashes qui frappent et attirent les ennemis que tu frôles. Le troisième te ramène au nuage laissé au départ : c''est ton retour, ne le dépense pas trop tôt.', 'Fumée'),
('nightcrawler-5', (select id from public.heroes where slug = 'nightcrawler'), null, null, 'Placement', 'Comment Nightcrawler apporte-t-il le plus à son équipe ?', '["En créant des occasions pour ses divers, puis en revenant en sécurité", "En restant au fond à lancer des grenades", "En jouant seul sur un flanc toute la partie", "En gardant toutes ses capacités pour fuir"]'::jsonb, 0, 'Ses soins sont faibles pour un Strategist : son kit sert à rejoindre ses divers, attirer les ennemis, sauver ou envoyer un allié. Il brille avec Venom, Spider-Man ou Daredevil, et beaucoup moins en file solo.', 'Plan de jeu'),
('loki-5', (select id from public.heroes where slug = 'loki'), null, null, 'Soins', 'Où viser avec Loki pour soigner ta ligne de front ?', '["Le sol, au milieu de mes alliés : seule l''explosion soigne", "La tête de l''allié le plus bas en vie", "Le torse de mon tank, pour un coup direct", "En l''air, au-dessus du groupe"]'::jsonb, 0, 'Le projectile ne fait rien par lui-même : tout le soin est dans l''explosion, et il est le même partout dans la zone. Viser le sol touche plusieurs alliés d''un coup, et tes clones tirent au même endroit.', 'Projectiles mystiques')
on conflict (key) do update set hero_id = excluded.hero_id, map_id = excluded.map_id, guide_slug = excluded.guide_slug, topic = excluded.topic, prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, section = excluded.section, active = true;
